            let resource = match repository.resolve_by_name(calendar_id, resource_name).await {
                Ok(Some(resource)) => resource,
                Ok(None) => return dav_resource_not_found(),
                Err(_) => return dav_server_error(),
            };
            let event = match EventRepository::new(accounts.pool().clone())
                .event(calendar_id, resource.event_id)
                .await
            {
                Ok(Some(event)) => event,
                Ok(None) => return dav_resource_not_found(),
                Err(_) => return dav_server_error(),
            };
            let recurring: bool = sqlx::query_scalar(
                "SELECT EXISTS(
                    SELECT 1 FROM events WHERE id = ? AND recurrence_rule IS NOT NULL
                 )",
            )
            .bind(resource.event_id)
            .fetch_one(accounts.pool())
            .await
            .unwrap_or(false);
            if recurring {
                return dav_resource_not_found();
            }
            let Some((ical, etag)) = ical_and_etag(&resource, &event, access) else {
                return dav_resource_not_found();
