                StatusCode::OK,
                [
                    (header::CONTENT_TYPE, "text/calendar; charset=utf-8"),
                    (header::ETAG, etag.as_str()),
                    (header::CONTENT_LENGTH, content_length.as_str()),
                ],
                ical,
            )
                .into_response();
            if head {
